import type { SupabaseClient } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";

/**
 * Hand-maintained schema types for the Phase 0B tenancy tables.
 *
 * `src/integrations/supabase/types.ts` is generated by the Lovable migration
 * system, which is bound to Lovable Cloud. This project uses an external
 * Supabase project, so the tenancy schema is typed here instead. Keep this in
 * sync with db/migrations/*.sql.
 */
export type OrgRole = "owner" | "admin" | "member";

export type OctapodDatabase = {
  public: {
    Tables: {
      organizations: {
        Row: { id: string; name: string; created_at: string };
        Insert: { id?: string; name: string; created_at?: string };
        Update: { id?: string; name?: string; created_at?: string };
        Relationships: [];
      };
      org_members: {
        Row: {
          org_id: string;
          user_id: string;
          role: OrgRole;
          user_email: string | null;
          created_at: string;
        };
        Insert: {
          org_id: string;
          user_id: string;
          role?: OrgRole;
          user_email?: string | null;
          created_at?: string;
        };
        Update: {
          org_id?: string;
          user_id?: string;
          role?: OrgRole;
          user_email?: string | null;
          created_at?: string;
        };
        Relationships: [];
      };
    };
    Views: Record<string, never>;
    Functions: Record<string, never>;
    Enums: { org_role: OrgRole };
    CompositeTypes: Record<string, never>;
  };
};

/** The shared browser client, typed against the tenancy schema. RLS applies. */
export const db = supabase as unknown as SupabaseClient<OctapodDatabase>;
